// Auto-generated Pre-Trained Weights
import { deserializeWeights } from '../modules/deserialize.js';

const BASE64_DATA = "";

let cachedWeights = null;

export function getTrainedModelWeights() {
  if (!cachedWeights) {
    const u8 = Uint8Array.fromBase64(BASE64_DATA);
    cachedWeights = deserializeWeights(u8);
  }
  return cachedWeights;
}
